function minMaxDifference(num) {
  const digits = String(num);
  let largest = digits;
  for (const digit of digits) {
    if (digit !== '9') {
      largest = digits.replaceAll(digit, '9');
      break;
    }
  }
  const smallest = digits.replaceAll(digits[0], '0');
  return Number(largest) - Number(smallest);
}

