function generate(rand, size) {
  const length = size === 'large' ? 8 + Math.floor(rand() * 2) : 1 + Math.floor(rand() * 8);
  if (length === 9) return [100000000];
  // Draw digits from a small pool so that repeated digits are common.
  const pool = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => Math.floor(rand() * 10));
  let text = '';
  for (let i = 0; i < length; i++) {
    const digit = rand() < 0.25 ? 9 : pool[Math.floor(rand() * pool.length)];
    text += i === 0 && digit === 0 ? '1' : String(digit);
  }
  return [Number(text)];
}
